const coverage=[['MSFT','Microsoft','Quality compounder','12-24M','8.6','Investor event Sep 22','$447.67','+2.4%','9.4','6.2','Improving'],['ASML','ASML Holding','AI capex bottleneck','12-18M','8.2','Earnings Oct 15','EUR 823.10','-1.2%','9.2','5.8','Stable'],['V','Visa','Payments compounder','18-36M','7.9','Results Oct 28','$336.24','+0.7%','9.0','6.7','Improving'],['NESN','Nestle','Margin recovery','6-12M','7.1','Sales update Oct 16','CHF 80.10','+0.3%','8.1','7.4','Turning']];
const ideas=document.querySelector('#ideas');if(ideas)ideas.innerHTML=coverage.map(a=>'<tr><td class="assetname"><b>'+a[0]+' - '+a[1]+'</b><small>Global equities</small></td><td>'+a[2]+'</td><td><span class="badge">'+a[3]+'</span></td><td class="conviction">'+a[4]+' / 10</td><td>'+a[5]+'</td></tr>').join('');
const rows=document.querySelector('#watchlistRows');if(rows)rows.innerHTML=coverage.map(a=>'<tr><td class="assetname"><b>'+a[0]+'</b><small>'+a[1]+'</small></td><td>'+a[6]+'</td><td class="'+(a[7].includes('-')?'red':'positive')+'">'+a[7]+'</td><td>'+a[8]+' / 10</td><td>'+a[9]+' / 10</td><td>'+a[10]+'</td><td><span class="badge">'+a[4]+' / 10</span></td><td>'+a[5]+'</td></tr>').join('');
const labels={dashboard:'COMMAND CENTER',research:'RESEARCH COCKPIT',watchlist:'ACTIVE WATCHLIST',calendar:'EVENT CALENDAR',briefing:'DAILY BRIEFING',reports:'AI RESEARCH REPORTS',chat:'ANALYST COPILOT',universe:'ASSET UNIVERSE'};
function go(view){document.querySelectorAll('.view').forEach(v=>v.classList.remove('visible'));document.getElementById(view).classList.add('visible');document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));document.querySelector('#crumb').textContent=labels[view];window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.view)));
document.querySelectorAll('.suggestions button').forEach(b=>b.onclick=()=>{document.querySelector('#chatInput').value=b.textContent;document.querySelector('#chatForm').requestSubmit()});
document.querySelector('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#chatInput'),q=input.value.trim();if(!q)return;const box=document.querySelector('#messages');box.insertAdjacentHTML('beforeend','<div class="message" style="margin:16px 0 0 auto;background:#203d34"><small>YOU - NOW</small><p>'+q.replace(/</g,'&lt;')+'</p></div>');input.value='';setTimeout(()=>box.insertAdjacentHTML('beforeend','<div class="message bot" style="margin-top:16px"><small>COPILOT - NOW</small><p>Demo response: a production copilot will retrieve filings, transcripts, estimates and validated news, then separate facts, assumptions, catalysts and risks with source links.</p></div>'),350)});
const universe=[['BTC','Bitcoin','Crypto','BTCUSD','High','Macro-sensitive store-of-value exposure.','BTC'],['ETH','Ethereum','Crypto','ETHUSD','High','Protocol adoption with fee, staking and regulatory risk.','ETH'],['DOGE','Dogecoin','Memecoin','DOGEUSD','Very high','Narrative-led asset; treat as a capped-risk satellite only.','DOGE'],['QQQ','Invesco QQQ','Index / ETF','NASDAQ:QQQ','Medium','US growth and technology factor exposure.','QQQ'],['CAC','CAC 40','Index','EURONEXT:PX1','Medium','French large-cap / euro-area exposure.','CAC'],['MC','LVMH','French equity','EPA:MC','Medium','Luxury franchise; monitor China demand and margin cadence.','MC'],['RKLB','Rocket Lab','Space','NASDAQ:RKLB','Very high','Event and financing risk are material.','RKLB']];
const uv=document.createElement('section');uv.id='universe';uv.className='view';uv.innerHTML='<div class="titlebar compact"><div><p class="eyebrow">CROSS-ASSET DISCOVERY</p><h1>Asset universe</h1><p class="sub">Equities, ETFs, indices, crypto, memecoins and themes. Prototype research only.</p></div><button class="primary" id="localLogin">Create local workspace</button></div><div class="assetfilters"><button class="filter on" data-type="All">All assets</button><button class="filter" data-type="Crypto">Crypto</button><button class="filter" data-type="Memecoin">Memecoins</button><button class="filter" data-type="Index">Indices / ETFs</button><button class="filter" data-type="French">France</button><button class="filter" data-type="Space">Space</button></div><div class="universegrid" id="universeGrid"></div><p class="universe-note">No orders are executed. External links only open independent research platforms.</p>';document.querySelector('main').appendChild(uv);
const nav=document.createElement('button');nav.className='nav';nav.dataset.view='universe';nav.innerHTML='<span>o</span> Asset universe';document.querySelector('.sidebar nav p').insertAdjacentElement('beforebegin',nav);nav.onclick=()=>go('universe');
function renderUniverse(type){const data=universe.filter(a=>type==='All'||a[2].includes(type));document.querySelector('#universeGrid').innerHTML=data.map(a=>'<article class="assetcard"><div class="assetcard-top"><span class="assetglyph">'+a[6]+'</span><div><small>'+a[2]+'</small><h3>'+a[1]+' <em>'+a[0]+'</em></h3></div><b class="risk">'+a[4]+' risk</b></div><p>'+a[5]+'</p><div class="riskbar"><i style="width:'+(a[4]==='Medium'?48:a[4]==='High'?72:94)+'%"></i></div><div class="assetactions"><button class="analyse" data-symbol="'+a[3]+'">Analyse risk</button><a target="_blank" rel="noreferrer" href="https://www.tradingview.com/symbols/'+a[3]+'/">TradingView</a><a target="_blank" rel="noreferrer" href="https://traderepublic.com/">Trade Republic</a></div></article>').join('');document.querySelectorAll('.analyse').forEach(x=>x.onclick=()=>showRisk(x.dataset.symbol))}renderUniverse('All');
document.querySelectorAll('.filter').forEach(x=>x.onclick=()=>{document.querySelectorAll('.filter').forEach(y=>y.classList.remove('on'));x.classList.add('on');renderUniverse(x.dataset.type)});
const modal=document.createElement('dialog');modal.className='hmodal';modal.innerHTML='<button class="modalclose">x</button><div id="modalBody"></div>';document.body.appendChild(modal);modal.querySelector('.modalclose').onclick=()=>modal.close();
function showRisk(symbol){modal.querySelector('#modalBody').innerHTML='<p class="eyebrow">RISK LENS - '+symbol+'</p><h2>Define risk before acting.</h2><p>This view is educational. It cannot determine whether an instrument is suitable for your personal situation.</p><div class="risklens"><span>Volatility</span><b>Set a maximum portfolio loss first</b><span>Liquidity</span><b>Check spreads and market depth</b><span>Event risk</span><b>Review macro, earnings and protocol events</b><span>Counter-thesis</span><b>Write what invalidates your thesis</b></div><button class="primary" id="ackRisk">I understand</button>';modal.showModal();modal.querySelector('#ackRisk').onclick=()=>modal.close()}
function localLogin(){modal.querySelector('#modalBody').innerHTML='<p class="eyebrow">LOCAL WORKSPACE</p><h2>Save research on this device.</h2><p>Free prototype mode. No online account is created; the session stays in this browser.</p><label class="field">Display name<input id="localName" placeholder="Alex"></label><button class="primary" id="saveLocal">Start workspace</button>';modal.showModal();modal.querySelector('#saveLocal').onclick=()=>{const n=document.querySelector('#localName').value||'Research member';localStorage.setItem('horizonUser',n);document.querySelector('.user b').textContent=n;modal.close();toast('Workspace saved locally')}}document.querySelector('#localLogin').onclick=localLogin;document.querySelector('.user').onclick=localLogin;const saved=localStorage.getItem('horizonUser');if(saved)document.querySelector('.user b').textContent=saved;
function toast(msg){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
document.querySelector('.search').onclick=()=>{modal.querySelector('#modalBody').innerHTML='<p class="eyebrow">COMMAND SEARCH</p><h2>Find a research workflow</h2><div class="commandlist"><button data-go="universe">Browse all asset classes</button><button data-go="research">Open Microsoft research</button><button data-go="chat">Ask Analyst Copilot</button></div>';modal.showModal();modal.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{modal.close();go(x.dataset.go)})};
document.querySelectorAll('.textbtn,.dots,.primary').forEach(x=>{if(!x.onclick&&!x.dataset.view&&!x.id)x.onclick=()=>toast('This workflow is ready for the Neon plus data-provider phase.')});
const extra=document.createElement('style');extra.textContent='.assetfilters{display:flex;gap:8px;flex-wrap:wrap;margin:4px 0 18px}.filter{border:1px solid var(--line);background:#0c1a17;color:#a5b5af;padding:8px 11px;border-radius:16px;font-size:11px}.filter.on{background:#213d31;color:var(--green);border-color:#426a58}.universegrid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.assetcard{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:18px}.assetcard-top{display:flex;align-items:start;gap:10px}.assetglyph{width:32px;height:32px;border-radius:8px;background:#1b3a30;color:var(--lime);display:grid;place-items:center;font-weight:700}.assetcard small{font:9px DM Mono;color:var(--muted)}.assetcard h3{margin:4px 0 0;font-size:14px}.assetcard h3 em{font:10px DM Mono;color:var(--muted);font-style:normal}.risk{margin-left:auto;font:9px DM Mono;padding:4px 5px;border-radius:3px;background:#3c311d;color:var(--yellow)}.assetcard>p{min-height:51px;font-size:11px;line-height:1.5;color:#aebbb7}.riskbar{height:4px;background:#263c35;margin:12px 0}.riskbar i{display:block;height:100%;background:var(--green)}.assetactions{display:flex;gap:9px;flex-wrap:wrap}.assetactions button,.assetactions a{border:0;background:transparent;color:var(--green);font-size:10px;padding:0;text-decoration:none}.universe-note{font-size:10px;color:var(--muted);margin-top:16px}.hmodal{width:min(500px,calc(100vw - 32px));background:#10221e;border:1px solid #45745f;color:var(--ink);padding:28px;border-radius:8px}.hmodal::backdrop{background:#010807c9}.modalclose{float:right;background:transparent;border:0;font-size:23px;color:var(--muted)}.hmodal h2{font-size:24px;letter-spacing:-.04em;margin:0 0 12px}.hmodal>div>p:not(.eyebrow){color:#b1c0ba;line-height:1.55;font-size:12px}.risklens{display:grid;grid-template-columns:1fr 1.4fr;border-top:1px solid var(--line);margin:18px 0}.risklens span,.risklens b{padding:10px 0;border-bottom:1px solid var(--line);font-size:11px}.risklens span{color:var(--muted)}.risklens b{font-weight:500}.field{display:block;font-size:11px;color:var(--muted);margin:16px 0}.field input{display:block;width:100%;margin-top:6px;padding:11px;background:#081512;color:white;border:1px solid #3a5a50;border-radius:4px}.commandlist{margin:16px 0}.commandlist button{width:100%;text-align:left;background:#132a24;border:0;border-bottom:1px solid var(--line);padding:12px;color:#c0cec8;font-size:12px}.toast{position:fixed;bottom:24px;right:24px;transform:translateY(20px);opacity:0;background:#18362c;border:1px solid #4e816a;color:#d6eee2;padding:12px 15px;border-radius:5px;font-size:12px;transition:.2s}.toast.show{transform:none;opacity:1}@media(max-width:1050px){.universegrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.universegrid{grid-template-columns:1fr}}';document.head.appendChild(extra);
